    # Jarmo's used methods:
    def request_reservation_lock(self, uuid, duration=600, clientId=''):
        """
            Wrapper for create_reservation_lock.

            Attributes:
                uuid (str): Reservation's ID.
                duration (int): Reservation's duration in seconds.
                clientId (str): ID provided by client to identify itself. This
                    can be used solely for client-side checking of lock
                    ownership when retrieving lock status. The application does
                    not use this ID when client updates topology.

            Returns:
                Same response as create_reservation_lock method.
        """

        return self.create_reservation_lock(uuid, duration=duration, clientId=clientId)

    def get_topology_by_id(self, topology_id):
        """
            Wrapper for get_topology.

            Attributes:
                topology_id (str): Reservation's ID.

            Returns:
                Same response as get_topology method.
        """

        return self.get_topology(topology_id)

    def get_topology_by_name(self, tl_or_conf):
        """
            Method searches topologies by given name.

            Attributes:
                tl_or_conf (str): Topology name.

            Returns:
                JSON dict with searched topology. If topology isn't found, None
                is returned.
        """
        response = self.get_topologies(filter="name::" + tl_or_conf)
        for topology in response["topologies"]:
            if topology["name"] in tl_or_conf:
                return topology
        return None

    def get_reservations_by_criteria(
            self, filtering_criteria="", start_after=None, end_before=None
    ):
        """
            Wrapper for get_reservations.

            Attributes:
                filtering_criteria (str): All filter parameters.
                start_after (int): Timestamp of the beginning of custom period.
                end_before (int): Timestamp of the ending of custom period.

            Returns:
                Same response as get_reservations method.
        """

        return self.get_reservations(
            filter=filtering_criteria, startAfter=start_after,
            endBefore=end_before
        )

    def reserve_topology(self, name, topology_id, duration, **kwargs):
        """
            Wrapper for create_reservation.

            Attributes:
                name (str): Topology name.
                topology_id (str): Topology ID.
                duration (int): Reservation duration in seconds.
                kwargs (dict): Additional parameters to reservation. available
                    at velocity/api/doc#reservation-service-v6-post-/reservation

            Returns:
                Same response as create_reservation method.
        """

        body = {
            "name": name,
            "description": "",
            "start": None,
            "end": None,
            "topologyId": topology_id,
            "duration": duration,
            "isRecurrent": False,
            "recurrence": None,
            "resources": None,
            "startTestCaseId": None,
            "endTestCaseId": None,
            "intervalToRunEndTestCase": None,
            "notes": None
        }
        for key in kwargs:
            body[key] = kwargs[key]
        return self.create_reservation(body)

